def list_html(items): return ''.join(f'<li>{html.escape(x)}</li>' for x in items)
def links_html(items):
 return ''.join(
  f'<a href="{href}"' + (' target="_blank" rel="noopener"' if href.startswith('http') else '') + f'><strong>{html.escape(label)}</strong><span>Learn more</span></a>'
  for label,href in items
 )
def faq_html(items,slug):
 out=[]
 for i,(q,a) in enumerate(items,1):
  out.append(f'<div class="financing-faq"><h3 class="h5">{html.escape(q)}</h3><p>{html.escape(a)}</p></div>')
 return ''.join(out)
