def rw(path,text):
 newline='\r\n' if '\r\n' in text else '\n'; text=text.replace('\r\n','\n')
 if newline=='\r\n': text=text.replace('\n','\r\n')
 with open(path,'w',encoding='utf-8',newline='') as f:f.write(text)
for filename,data in PAGES.items():
 p=ROOT/filename
 with open(p,encoding='utf-8',newline='') as f:src=f.read()
 replacement=START+'\n'+block(data)+'\n'+END
 pattern=re.compile(re.escape(START)+r'.*?'+re.escape(END),re.S)
 if not pattern.search(src): raise SystemExit(f'missing pathway: {filename}')
 rw(p,pattern.sub(replacement,src))
print(f'Built {len(PAGES)} unique financing landing-page sections.')
